package com.kivkung.universalclipboard;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.*;import org.json.*;
/** Isolated instrumentation for actual Android clipboard/history/provider behavior. */
public final class HistorySmoke extends Instrumentation {
 StringBuilder report=new StringBuilder();void check(boolean ok,String name)throws Exception{if(!ok)throw new Exception(name);report.append("PASS "+name+"\n");android.util.Log.i("HistorySmoke","PASS "+name);}
 public void onCreate(Bundle b){super.onCreate(b);start();}public void onStart(){Bundle b=new Bundle();try{test();b.putString("stream",report.toString());finish(Activity.RESULT_OK,b);}catch(Throwable e){b.putString("stream",report+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,b);}}
 JSONObject offer(String id,String name,byte[] bytes)throws Exception{return Wire.obj("type","file.offer","from","history-test-host","transferId",id,"name",name,"kind","file","mime","application/octet-stream","size",bytes.length,"hash",Wire.hash(bytes));}
 JSONObject receive(IncomingClipboard r,JSONObject offer,byte[] bytes)throws Exception{r.handle(offer);if(bytes.length>0)r.handle(Wire.obj("type","file.chunk","from","history-test-host","transferId",offer.getString("transferId"),"offset",0,"sequence",0,"data",Base64.getEncoder().encodeToString(bytes)));return r.handle(Wire.obj("type","file.finish","from","history-test-host","transferId",offer.getString("transferId")));}
 void test()throws Exception{Context c=getTargetContext();MainActivity a=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));long end=SystemClock.elapsedRealtime()+5000;while(!a.hasWindowFocus()&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);check(a.hasWindowFocus(),"focused app can inspect clipboard");IncomingClipboard r=new IncomingClipboard(c,(x,y,z)->{});HistoryStore h=new HistoryStore(c);byte[] bytes={0,1,2,(byte)255,0,19};String id=Wire.hash(Wire.utf("binary-"+System.nanoTime()));JSONObject o=offer(id,"fixture.bin",bytes);receive(r,o,bytes);Uri uri=c.getSystemService(ClipboardManager.class).getPrimaryClip().getItemAt(0).getUri();check(uri!=null&&uri.getAuthority().endsWith(".history"),"generic binary published to clipboard local content URI");try(InputStream in=c.getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();int b;while((b=in.read())!=-1)out.write(b);check(Arrays.equals(bytes,out.toByteArray()),"generic binary bytes unchanged");}try(android.database.Cursor cursor=c.getContentResolver().query(uri,null,null,null,null)){check(cursor.moveToFirst()&&cursor.getString(cursor.getColumnIndex("_display_name")).equals("fixture.bin")&&cursor.getLong(cursor.getColumnIndex("_size"))==bytes.length,"provider display filename/size metadata");}check("application/octet-stream".equals(c.getContentResolver().getType(uri)),"provider MIME metadata");boolean denied=false;try{c.getContentResolver().openFileDescriptor(uri,"w").close();}catch(Exception ex){denied=true;}check(denied,"generic provider denies write");int count=h.list().size();receive(r,o,bytes);check(h.list().size()==count,"completed retry does not duplicate history");
 shell("am start -n com.kivkung.universalclipboard.test/com.kivkung.universalclipboard.GenericReadActivity --eu uri '"+uri+"'");String external="";end=SystemClock.elapsedRealtime()+5000;while(!external.equals("OK "+Wire.hash(bytes)+" "+uri)&&SystemClock.elapsedRealtime()<end){try(android.database.Cursor cursor=c.getContentResolver().query(Uri.parse("content://com.kivkung.universalclipboard.test.fixture/generic"),null,null,null,null)){if(cursor!=null&&cursor.moveToFirst())external=cursor.getString(0);}Thread.sleep(50);}check(external.equals("OK "+Wire.hash(bytes)+" "+uri),"separate app reads generic URI with clipboard grant: "+external);startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));
 String zero=Wire.hash(Wire.utf("zero-"+System.nanoTime()));receive(r,offer(zero,"empty.bin",new byte[0]),new byte[0]);check(h.list().get(0).getJSONArray("files").getJSONObject(0).getLong("size")==0,"zero-byte file completes and enters history");String batch=Wire.hash(Wire.utf("batch-"+System.nanoTime()));String f1=Wire.hash(Wire.utf(batch+"1")),f2=Wire.hash(Wire.utf(batch+"2"));JSONObject p1=offer(f1,"one-"+batch.substring(0,12)+".bin",bytes),p2=offer(f2,"two-"+batch.substring(0,12)+".bin",new byte[0]);org.json.JSONArray manifest=new org.json.JSONArray();for(JSONObject p:new JSONObject[]{p1,p2}){JSONObject m=new JSONObject(p.toString());m.remove("type");m.remove("from");manifest.put(m);}r.handle(Wire.obj("type","file.batch.offer","from","history-test-host","batchId",batch,"count",2,"files",manifest));String before=h.list().get(0).getString("id");p1.put("batchId",batch);p1.put("index",0);p2.put("batchId",batch);p2.put("index",1);receive(r,p1,bytes);check(h.list().get(0).getString("id").equals(before),"validated batch member alone does not append history");boolean incomplete=false;try{r.handle(Wire.obj("type","file.batch.finish","from","history-test-host","batchId",batch));}catch(Exception ex){incomplete=true;}check(incomplete&&h.list().get(0).getString("id").equals(before),"incomplete batch fails without evicting history");receive(r,p2,new byte[0]);r.handle(Wire.obj("type","file.batch.finish","from","history-test-host","batchId",batch));check(h.list().get(0).getJSONArray("files").length()==2&&c.getSystemService(ClipboardManager.class).getPrimaryClip().getItemCount()==2,"batch commits once and copies entire file list");
 String pinned=h.list().get(0).getString("id");h.save(pinned);Uri[] exports=new Uri[2];String[] exportNames={p1.getString("name"),p2.getString("name")};try(android.database.Cursor cursor=c.getContentResolver().query(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{"_id","_display_name"},"_display_name IN (?, ?)",exportNames,null)){if(cursor!=null)while(cursor.moveToNext()){for(int j=0;j<2;j++)if(exportNames[j].equals(cursor.getString(1)))exports[j]=ContentUris.withAppendedId(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,cursor.getLong(0));}}check(exports[0]!=null&&exports[1]!=null,"Save creates two permanent MediaStore Downloads exports");check(Arrays.equals(bytes,read(c,exports[0]))&&read(c,exports[1]).length==0,"Downloads exports preserve binary and zero-byte contents");File protectedFile=h.payload(pinned,0);android.os.ParcelFileDescriptor reader=c.getContentResolver().openFileDescriptor(h.uri(pinned,0),"r");for(int i=0;i<6;i++){String t="history text "+i;r.handle(Wire.obj("type","clipboard.text","from","history-test-host","text",t,"hash",Wire.hash(Wire.utf(t))));}check(h.list().size()==5&&h.list().get(0).getString("text").equals("history text 5")&&h.list().get(4).getString("text").equals("history text 1"),"six successes retain latest five in correct FIFO order");check(protectedFile.exists(),"eviction preserves leased and open payload");check(Arrays.equals(bytes,read(c,exports[0]))&&read(c,exports[1]).length==0,"permanent Downloads exports remain unchanged after FIFO eviction");reader.close();check(new HistoryStore(c).list().get(0).getString("text").equals("history text 5"),"history metadata reload survives receiver/store restart");r.handle(Wire.obj("type","file.batch.finish","from","history-test-host","batchId",batch));check("history text 5".contentEquals(c.getSystemService(ClipboardManager.class).getPrimaryClip().getItemAt(0).getText()),"completed batch retry never republishes an older clipboard");
 long savedBudget=Config.prefs(c).getLong("historyBudgetBytes",HistoryStore.DEFAULT_BUDGET);String reservation=Wire.hash(Wire.utf("reservation-"+System.nanoTime()));JSONObject future=offer(Wire.hash(Wire.utf(reservation+"member")),"future.bin",new byte[0]);future.put("size",1024*1024);future.remove("type");future.remove("from");long used=HistoryStore.tree(c.getFilesDir());Config.prefs(c).edit().putLong("historyBudgetBytes",used+1024*1024+100*1024).commit();r.handle(Wire.obj("type","file.batch.offer","from","history-test-host","batchId",reservation,"count",1,"files",new org.json.JSONArray().put(future)));JSONObject blocked=offer(Wire.hash(Wire.utf(reservation+"blocked")),"blocked.bin",new byte[0]);blocked.put("size",256*1024);boolean reservedFull=false;try{r.handle(blocked);}catch(Exception ex){reservedFull=ex.getMessage().contains("storage full");}check(reservedFull,"unreceived batch manifest reserves entire promised size");r.handle(Wire.obj("type","file.batch.cancel","from","history-test-host","batchId",reservation));r.handle(blocked);r.handle(Wire.obj("type","file.cancel","from","history-test-host","transferId",blocked.getString("transferId")));check(true,"batch cancellation releases future-byte reservation");Config.prefs(c).edit().putLong("historyBudgetBytes",savedBudget).commit();
 long budget=Config.prefs(c).getLong("historyBudgetBytes",HistoryStore.DEFAULT_BUDGET);Config.prefs(c).edit().putLong("historyBudgetBytes",1).commit();String top=h.list().get(0).getString("id");boolean full=false;try{r.handle(offer(Wire.hash(Wire.utf("budget-"+System.nanoTime())),"large.bin",bytes));}catch(Exception ex){full=ex.getMessage().contains("storage full");}finally{Config.prefs(c).edit().putLong("historyBudgetBytes",budget).commit();}check(full&&h.list().get(0).getString("id").equals(top),"storage pressure rejects clearly without evicting successful history");JSONObject unsafe=offer(Wire.hash(Wire.utf("unsafe")),"../evil",bytes);boolean bad=false;try{r.handle(unsafe);}catch(Exception ex){bad=true;}check(bad,"unsafe filename rejected");
 String stable=h.list().get(0).getString("id");JSONObject corrupt=offer(Wire.hash(Wire.utf("corrupt-"+System.nanoTime())),"corrupt.bin",bytes);corrupt.put("hash",Wire.hash(new byte[]{42}));boolean hashFailure=false;try{receive(r,corrupt,bytes);}catch(Exception ex){hashFailure=true;}check(hashFailure&&h.list().get(0).getString("id").equals(stable),"SHA-256 failure never appends or evicts history");r.handle(Wire.obj("type","file.cancel","from","history-test-host","transferId",corrupt.getString("transferId")));
 String cancelBatch=Wire.hash(Wire.utf("cancel-batch-"+System.nanoTime()));JSONObject cancelOffer=offer(Wire.hash(Wire.utf(cancelBatch+"file")),"cancel.bin",bytes);JSONObject cancelManifest=new JSONObject(cancelOffer.toString());cancelManifest.remove("type");cancelManifest.remove("from");r.handle(Wire.obj("type","file.batch.offer","from","history-test-host","batchId",cancelBatch,"count",1,"files",new org.json.JSONArray().put(cancelManifest)));cancelOffer.put("batchId",cancelBatch);cancelOffer.put("index",0);receive(r,cancelOffer,bytes);r.handle(Wire.obj("type","file.batch.cancel","from","history-test-host","batchId",cancelBatch));boolean cancelFailure=false;try{r.handle(Wire.obj("type","file.batch.finish","from","history-test-host","batchId",cancelBatch));}catch(Exception ex){cancelFailure=true;}check(cancelFailure&&h.list().get(0).getString("id").equals(stable),"cancelled validated batch never appends successful history");
 String entryId=Wire.hash(Wire.utf("stable-text-"+System.nanoTime())),oldText="stable original text";JSONObject textReceipt=Wire.obj("type","clipboard.text","from","history-test-host","entryId",entryId,"text",oldText,"hash",Wire.hash(Wire.utf(oldText)));String oldEntry=r.handle(textReceipt).getString("historyId");for(int j=0;j<6;j++){String newer="text retry newer "+j;r.handle(Wire.obj("type","clipboard.text","from","history-test-host","entryId",Wire.hash(Wire.utf(entryId+":"+j)),"text",newer,"hash",Wire.hash(Wire.utf(newer))));}JSONObject retired=h.get(oldEntry);retired.put("leaseUntil",0);h.write(retired);h.cleanup();check(!h.metadata(oldEntry).exists(),"old text history metadata physically evicts after lease expiry");String newest=h.list().get(0).getString("id");new IncomingClipboard(c,(x,y,z)->{}).handle(textReceipt);check(h.list().size()==5&&h.list().get(0).getString("id").equals(newest)&&"text retry newer 5".contentEquals(c.getSystemService(ClipboardManager.class).getPrimaryClip().getItemAt(0).getText()),"durable stable text entryId retry never resurrects evicted history or changes newer clipboard");}
 byte[] read(Context c,Uri uri)throws Exception{try(InputStream in=c.getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[1024];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);return out.toByteArray();}}
 void shell(String command)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command))){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
}
